from app.database.connection import SessionLocal
from app.models.content import Alias, Content, Reference

ARTICLES = [
    ('لحن غولغوثا (قانون الدفنة)', 'golgotha-hymn', 'اللحن ده بيتقال مرة واحدة بس في السنة في نهاية صلاة الساعة 12 من يوم الجمعة العظيمة، وأبونا والشمامسة بيعملوا طقس الدفنة وبيكفنوا أيقونة الصلبوت وسط الورد والحنوط والأطياب. كلمات اللحن بالقبطي واليوناني، وبتوصف صلب السيد المسيح بين لصين، وطلب اللص اليمين إن ربنا يفتكره في ملكوته، وبعدين مجيء يوسف الرامي ونيقوديموس عشان يكفنوا جسد الرب ويدفنوه في القبر الجديد.', ['قانون الدفنة','لحن الجلجثة بالعبرانية','لحن غولغوثا أم ميت هيفريؤس','لحن دفنة الجمعة العظيمة','لحن تجنيز المسيح'], ['متى 27: 33–60','لوقا 23: 39–53','يوحنا 19: 38–42']),
    ('لحن ثوك تي تي جوم (لك القوة والمجد)', 'thok-te-ti-gom', 'ده اللحن الرئيسي اللي بنردده في كل صلوات البصخة طول أسبوع الآلام بدل المزامير وصلاة الشكر. فكرته بسيطة وعميقة: الكنيسة بتقول للمسيح وهو في عز آلامه وضعفه الظاهري على الصليب: لك القوة والمجد والبركة والعزة إلى الأبد.', ['لحن لك القوة والمجد','تسبحة البصخة','لحن أسبوع الآلام','ثوك تي تي جوم','قانون البصخة المقدسة'], ['رؤيا 4: 11','رؤيا 5: 12–13','أخبار الأيام الأول 29: 11']),
    ('لحن أومونوجينيس (أيها الابن الوحيد)', 'o-monogenis', 'لحن يوناني مؤثر جدًا بيتقال في الساعة السادسة من يوم الجمعة العظيمة. اللحن ده بيلخص إيمان الكنيسة في المسيح: إن الابن الوحيد اللي مابيموتش بطبيعته الإلهية، تجسد من العذراء مريم وقَبِل الموت بالجسد على الصليب عشان يغلب الموت ويدينا الحياة الأبدية.', ['لحن أيها الابن الوحيد','لحن الساعة السادسة','لحن أومونوجينيس','تسبحة التجسد والفداء','لحن الجمعة العظيمة السادس'], ['يوحنا 1: 14','يوحنا 3: 16','فيلبي 2: 6–8','بطرس الأولى 3: 18']),
    ('لحن فاي إيتاف إنف (هذا الذي أصعد ذاته)', 'fai-etaf-enf', 'اللحن ده بيتقال في الساعة السادسة من الجمعة العظيمة وكمان في أعياد الصليب، وبيوضح إن المسيح قدّم نفسه ذبيحة حقيقية على الصليب أعظم بكتير من ذبائح العهد القديم لخلاص البشرية كلها.', ['لحن هذا الذي أصعد ذاته','لحن ذبيحة المساء','لحن فاي إيتاف إنف','لحن صلبوت الساعة السادسة','لحن الصليب'], ['أفسس 5: 2','عبرانيين 9: 11–14','عبرانيين 10: 12']),
    ('لحن تاي شوري (هذه المجمرة)', 'tai-shouri', 'لحن جميل ومعروف بيتقال في القداس الإلهي في الأيام العادية وقت قراية البولس. اللحن بيشبّه الست العذراء مريم بالمجمرة الذهب اللي في هيكل العهد القديم، زي ما المجمرة بتشيل الفحم المولع من غير ما تتحرق، العذراء شالت في بطنها السيد المسيح عشان يغفر خطايانا.', ['لحن هذه المجمرة','لحن البولس','لحن تاي شوري','لحن المجمرة الذهب','لحن العذراء في القداس'], ['خروج 25: 11','إشعياء 6: 6–7','عبرانيين 9: 4']),
]

def seed():
    db = SessionLocal()
    try:
        for title, slug, text, aliases, references in ARTICLES:
            if db.query(Content).filter_by(slug=slug).first(): continue
            article = Content(title=title, slug=slug, content_type='hymn', description='TEST CONTENT — supplied Egyptian Arabic article; review before production.', content=text, language='ar', status='approved')
            article.aliases = [Alias(alias=a, language='ar') for a in aliases]
            article.references = [Reference(reference_type='biblical_or_liturgical', reference_text=r) for r in references]
            db.add(article)
        db.commit()
    finally: db.close()
if __name__ == '__main__': seed()
